changeSet.sql:
ALTER TABLE obra_social_plan_prestacion ADD CONSTRAINT ck_obra_social_plan_prestacion_coherencia CHECK (
    (modalidad_cobertura = 'TOTAL' AND porcentaje_cobertura IS NULL AND coseguro IS NULL) OR
    (modalidad_cobertura = 'CARGO_FIJO' AND coseguro IS NOT NULL AND coseguro >= 0 AND porcentaje_cobertura IS NULL) OR
    (modalidad_cobertura = 'PORCENTUAL' AND porcentaje_cobertura IS NOT NULL AND porcentaje_cobertura >= 0 AND porcentaje_cobertura <= 100 AND coseguro IS NULL)
);
